import{c as a,Q as s,j as e,m as t}from"./chunks/framework.DK3sgdKX.js";const I="/PythonSTG/assets/name_sc-1.DYfjIiNL.png",l="data:image/svg+xml;base64,",C=JSON.parse('{"title":"独立资产工具指南","description":"","frontmatter":{},"headers":[],"relativePath":"EDITOR_TOOLS_GUIDE.md","filePath":"EDITOR_TOOLS_GUIDE.md","lastUpdated":1795193770000}'),d={name:"EDITOR_TOOLS_GUIDE.md"};function o(n,i,g,h,c,p){return s(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="独立资产工具指南" tabindex="-1">独立资产工具指南 <a class="header-anchor" href="#独立资产工具指南" aria-label="Permalink to &quot;独立资产工具指南&quot;">​</a></h1><p>本文介绍 PySTG 配套的独立可视化资产编辑器。代码驱动关卡编辑器见 <a href="./getting-started">快速开始</a> 和 <a href="./EDITOR_PRODUCT_VISION">编辑器设计概览</a>。</p><hr><h2 id="_1-工具一览" tabindex="-1">1. 工具一览 <a class="header-anchor" href="#_1-工具一览" aria-label="Permalink to &quot;1. 工具一览&quot;">​</a></h2><p>所有独立资产工具通过 <code>src.qt_compat</code> 使用 PySide6，统一采用 Catppuccin Mocha 暗色主题，公共代码位于 <code>tools/editor_common.py</code>。</p><table tabindex="0"><thead><tr><th>工具</th><th>脚本路径</th><th>用途</th></tr></thead><tbody><tr><td>工具箱启动器</td><td><code>tools/editor_launcher.py</code></td><td>集中启动下方 6 个资产工具</td></tr><tr><td>弹幕别名管理器</td><td><code>tools/bullet/bullet_alias_manager.py</code></td><td>维护弹型 + 颜色到精灵名的映射（<code>assets/bullet_aliases.json</code>）</td></tr><tr><td>纹理资产编辑器</td><td><code>tools/asset/asset_manager_qt.py</code></td><td>编辑精灵图集裁切区域、动画帧、激光三段与自机贴图</td></tr><tr><td>自机编辑器</td><td><code>tools/player/player_editor.py</code></td><td>编辑自机动画状态机、射击类型与子机配置</td></tr><tr><td>敌人别名管理器</td><td><code>tools/enemy/enemy_alias_manager.py</code></td><td>管理敌人贴图与别名映射</td></tr><tr><td>立绘渲染编辑器</td><td><code>tools/portrait_editor/run.py</code></td><td>调整对话立绘槽位、说话者位移与非说话者透明度/饱和度</td></tr><tr><td>背景编辑器</td><td><code>tools/stage/background_editor.py</code></td><td>浏览背景资源并编辑数据驱动背景配置</td></tr></tbody></table><h3 id="安装依赖" tabindex="-1">安装依赖 <a class="header-anchor" href="#安装依赖" aria-label="Permalink to &quot;安装依赖&quot;">​</a></h3><p>在仓库根目录安装开发依赖：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements-dev.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><hr><h2 id="_2-工具箱启动器" tabindex="-1">2. 工具箱启动器 <a class="header-anchor" href="#_2-工具箱启动器" aria-label="Permalink to &quot;2. 工具箱启动器&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/editor_launcher.py</span></span></code></pre></div><p>启动器以 2×3 卡片网格展示全部 6 个资产工具，点击卡片会在独立子进程中打开对应编辑器。</p><blockquote><p>注意：关闭启动器窗口时，会一并终止由该启动器拉起的子进程。如果需要独立常驻，可以直接运行单个工具的 Python 脚本。</p></blockquote><hr><h2 id="_3-弹幕别名管理器" tabindex="-1">3. 弹幕别名管理器 <a class="header-anchor" href="#_3-弹幕别名管理器" aria-label="Permalink to &quot;3. 弹幕别名管理器&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/bullet/bullet_alias_manager.py</span></span></code></pre></div><p>关卡脚本中使用抽象名称发弹（如 <code>bullet_type=&quot;ball_m&quot;, color=&quot;red&quot;</code>），引擎通过 <code>assets/bullet_aliases.json</code> 将其映射到具体的图集精灵名（如 <code>ball_mid1</code>）。本工具用于可视化维护这张映射表。</p><p><img src="`+I+'" alt="弹幕别名管理器界面"></p><h3 id="格子状态" tabindex="-1">格子状态 <a class="header-anchor" href="#格子状态" aria-label="Permalink to &quot;格子状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>颜色</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>🟢 绿色</td><td>已分配且精灵存在</td><td>正常</td></tr><tr><td>🟡 黄色</td><td>已分配但图集中找不到</td><td>需要重新指定或检查图集配置</td></tr><tr><td>🔴 红色</td><td>未分配</td><td>尚未配置映射</td></tr></tbody></table><h3 id="常用操作" tabindex="-1">常用操作 <a class="header-anchor" href="#常用操作" aria-label="Permalink to &quot;常用操作&quot;">​</a></h3><ul><li><strong>分配精灵</strong>：左键单击格子打开精灵选取器，支持按名称和所属图集过滤，双击缩略图确认。</li><li><strong>清除分配</strong>：右键单击格子选择“清除此格子”。</li><li><strong>增删类型 / 颜色</strong>：通过工具栏按钮或“编辑”菜单维护行列。</li><li><strong>验证与保存</strong>：点击工具栏“验证”检查全部映射是否有效，<code>Ctrl+S</code> 保存到 <code>assets/bullet_aliases.json</code>。</li></ul><p><img src="'+l+`" alt="精灵选取器界面示意图"></p><h3 id="输出格式" tabindex="-1">输出格式 <a class="header-anchor" href="#输出格式" aria-label="Permalink to &quot;输出格式&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mapping&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;ball_m&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;red&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ball_mid1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;blue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ball_mid2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;green&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ball_mid3&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>不同弹型在精灵图集中的编号顺序并不统一，使用别名表可以让脚本与底层图集编号解耦。</p><hr><h2 id="_4-纹理资产编辑器" tabindex="-1">4. 纹理资产编辑器 <a class="header-anchor" href="#_4-纹理资产编辑器" aria-label="Permalink to &quot;4. 纹理资产编辑器&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/asset/asset_manager_qt.py</span></span></code></pre></div><p>纹理资产编辑器直接调用引擎的 <code>UnifiedTextureManager</code>（<code>src/resource/unified_texture.py</code>），读写格式与游戏运行时一致，支持 <code>assets/images/{bullet,laser,player,enemy,item,background,ui}/</code> 和 <code>assets/players/*/</code> 下的配置。</p><p>主要功能：</p><ul><li>在纹理图集上直接框选精灵 <code>rect</code> 区域、按 <code>N × M</code> 网格批量切图</li><li>拖拽设置旋转/渲染中心点与圆形碰撞半径</li><li>编辑序列帧动画并实时播放预览</li><li>预览三段式激光（head / body / tail）与 16 色变体组</li><li>原子写回对应的图集 JSON 文件</li></ul><p>详细快捷键与已知限制见 <code>tools/asset/ASSET_MANAGER_QT_README.md</code>。</p><hr><h2 id="_5-自机编辑器" tabindex="-1">5. 自机编辑器 <a class="header-anchor" href="#_5-自机编辑器" aria-label="Permalink to &quot;5. 自机编辑器&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/player/player_editor.py</span></span></code></pre></div><p>用于可视化编辑 <code>assets/players/&lt;角色名&gt;/config.json</code>（当前仓库包含 <code>tao</code>、<code>orin</code>、<code>tenshi</code>、<code>sakuya</code>）：</p><ul><li>空闲 / 左移 / 右移等动画状态机及帧序列预览</li><li>主武器、副武器发射参数配置</li><li>子机（Option）位置偏移、动画与攻击配置</li><li>高速 / 低速移动速度与判定半径</li></ul><hr><h2 id="_6-其他独立工具" tabindex="-1">6. 其他独立工具 <a class="header-anchor" href="#_6-其他独立工具" aria-label="Permalink to &quot;6. 其他独立工具&quot;">​</a></h2><ul><li><strong>敌人别名管理器</strong>（<code>tools/enemy/enemy_alias_manager.py</code>）：维护敌人贴图与别名映射。</li><li><strong>立绘渲染编辑器</strong>（<code>tools/portrait_editor/run.py</code>）：实时预览并调整对话立绘的屏幕位置、焦点高亮与退场样式，写回 <code>assets/ui/dialog_portrait_layout.json</code>。</li><li><strong>背景编辑器</strong>（<code>tools/stage/background_editor.py</code>）：编辑数据驱动背景配置。</li></ul><hr><h2 id="_7-共享模块-tools-editor-common-py" tabindex="-1">7. 共享模块（<code>tools/editor_common.py</code>） <a class="header-anchor" href="#_7-共享模块-tools-editor-common-py" aria-label="Permalink to &quot;7. 共享模块（\`tools/editor_common.py\`）&quot;">​</a></h2><p>编写新的 Qt 资产工具时，可直接复用 <code>tools/editor_common.py</code> 提供的公共能力：</p><ul><li><strong>路径常量</strong>：<code>PROJECT_ROOT</code>、<code>ASSET_ROOT</code>、<code>BULLET_IMAGE_DIR</code>、<code>BULLET_ALIASES_PATH</code>、<code>PLAYERS_ROOT</code>。</li><li><strong>统一主题</strong>：<code>apply_dark_theme(widget)</code> 或 <code>DARK_THEME</code>。</li><li><strong>精灵加载与缓存</strong>：<code>load_all_bullet_sprites()</code>、<code>get_all_sprite_names()</code>、<code>get_sprite_entry_map()</code>、<code>PixmapCache</code>。</li><li><strong>别名读写</strong>：<code>load_bullet_aliases()</code>、<code>save_bullet_aliases()</code>、<code>generate_default_aliases()</code>。</li></ul><p>新增工具后，在 <code>tools/editor_launcher.py</code> 中添加对应的 <code>ToolCard</code> 即可接入统一启动器。</p><hr><h2 id="_8-常见问题" tabindex="-1">8. 常见问题 <a class="header-anchor" href="#_8-常见问题" aria-label="Permalink to &quot;8. 常见问题&quot;">​</a></h2><ul><li><strong>启动时报错缺少 <code>PySide6</code> 或找不到 <code>src</code></strong>：确认使用同一个 Python 环境，在仓库根目录执行 <code>python -m pip install -r requirements-dev.txt</code> 和 <code>python -m pip install -e .</code>。</li><li><strong>弹幕别名管理器网格为空</strong>：确认从仓库根目录启动，并检查 <code>assets/images/bullet/</code> 下是否存在图集 JSON 与 PNG。</li><li><strong>保存修改后游戏未生效</strong>：重启游戏即可加载新配置；调试弹幕别名、HUD 布局或激光配置时，也可以带 <code>--hot-reload</code> 启动游戏自动重载。</li></ul>`,50)])])}const m=a(d,[["render",o]]);export{C as __pageData,m as default};
